<script setup>import{inject}from'vue';const s=inject('clinicAdmin');const label=v=>v.replaceAll('.',' ').replace(/\b\w/g,c=>c.toUpperCase());const fmt=v=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));</script><template><section class="admin-card"><div class="card-heading"><h2>Clinic Activity</h2></div><div class="divide-y"><div v-for="item in s.activity.value" :key="item.id" class="grid gap-2 py-4 sm:grid-cols-[1fr_180px]"><div><p class="font-semibold">{{label(item.action)}}</p><p class="text-sm text-slate-500">Performed by platform administrator #{{item.actor_id}}</p></div><time class="text-sm text-slate-500">{{fmt(item.created_at)}}</time></div></div><p v-if="!s.activity.value.length" class="empty-state">No clinic activity recorded.</p></section></template>
